#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct ClaudeSettings {
    /// Resolved in the login PATH.
    #[schemars(extend("x-kelta-exec" = true))]
    pub binary: String,
    /// Semver; older → warning, hooks still attempted.
    pub min_version: String,
    /// SessionStart always uses a command hook.
    pub hook_transport: HookTransport,
    /// Kelta MCP server for Claude sessions.
    pub mcp: bool,
    /// Board-wide MCP writes (move, comment, edit, close any ticket by key); off = read-only board tools.
    pub mcp_board_writes: bool,
    /// At startup, offer to register Kelta's MCP in Claude Code (user scope); false = never ask.
    #[schemars(extend("x-kelta-scope" = ["global"]))]
    pub mcp_offer: bool,
    /// At startup, offer to register Kelta's hook relay in Claude Code's user settings, so sessions
    /// Kelta did not start show in Now (#345); false = never ask.
    #[schemars(extend("x-kelta-scope" = ["global"]))]
    pub hooks_offer: bool,
    /// Passed via `--allowedTools`.
    pub allowed_tools: Vec<String>,
    /// Appended to the generated `context.md`.
    /// Steers the session (which may auto-approve tools): inert from an untrusted repo file.
    #[schemars(extend("x-kelta-scope" = ["global", "project", "repo"], "x-kelta-exec" = true))]
    pub append_system_prompt: String,
    /// Appended before the prompt.
    #[schemars(extend("x-kelta-exec" = true))]
    pub extra_args: Vec<String>,
    /// Merged into the generated `--settings` hooks.
    #[schemars(extend("x-kelta-exec" = true))]
    pub extra_hooks: BTreeMap<String, serde_json::Value>,
    pub profiles: BTreeMap<String, ClaudeProfile>,
    pub prompt_templates: BTreeMap<String, String>,
    /// Claude IDE bridge: Claude sessions see Kelta as their IDE (ARCHITECTURE §8.5).
    pub ide_bridge: bool,
    /// Spend per work item (USD) past which its cost chip turns red; set it per project.
    pub budget_usd: Option<f64>,
    /// Live Claude processes start work may run at once; past it items wait `Queued` (0 = no cap).
    pub max_live: u32,
    /// Hold the queue while the 5h rate-limit usage (%) is at or above this; none = never hold.
    pub queue_hold_pct: Option<f64>,
    /// Park a work item's Claude once it has been done and seen, with no input, this long (min, 0 = off).
    pub auto_park_after_mins: u32,
}

impl Default for ClaudeSettings {
    fn default() -> Self {
        let plan = ClaudeProfile {
            model: "opus".into(),
            effort: ClaudeEffort::High,
            permission_mode: Some(PermissionMode::Plan),
        };
        Self {
            binary: "claude".into(),
            min_version: "2.1.200".into(),
            hook_transport: HookTransport::Command,
            mcp: true,
            mcp_board_writes: true,
            mcp_offer: true,
            hooks_offer: true,
            allowed_tools: vec!["mcp__kelta__*".into()],
            append_system_prompt: String::new(),
            extra_args: Vec::new(),
            extra_hooks: BTreeMap::new(),
            profiles: BTreeMap::from([
                ("default".to_owned(), ClaudeProfile::default()),
                ("review".to_owned(), plan.clone()),
                ("plan".to_owned(), plan),
            ]),
            prompt_templates: BTreeMap::from([
                (
                    "ticket".to_owned(),
                    "Work on {ticket.key}: {ticket.title}. The full ticket is in {run}/ticket.md. Read it, then propose a short plan before editing.".to_owned(),
                ),
                (
                    "review".to_owned(),
                    "Review PR {pr.url} ({pr.head} → {pr.base}). Focus on correctness, tests and risks. Do not edit files.".to_owned(),
                ),
                ("standalone".to_owned(), "{task}".to_owned()),
                (
                    "workflow".to_owned(),
                    "Run the saved workflow \"{workflow}\" with the JSON in {args} as its args. The ticket is {ticket.key}: {ticket.title}; its full text is in {file}.".to_owned(),
                ),
                (
                    "feedback".to_owned(),
                    "The review of {pr.url} left feedback, collected in {file}. Address each item (or say why not), run the tests, and commit the fixes. Do not push.".to_owned(),
                ),
                (
                    "checks".to_owned(),
                    "Checks failed on {pr.url}. Their names, links and log tails are in {file}. Reproduce each failure locally, fix it, run the tests, and commit the fixes. Do not push.".to_owned(),
                ),
                (
                    "conflicts".to_owned(),
                    "The rebase of {branch} onto {onto} stopped at commit {step} of {total} with conflicts, listed in {file}. Resolve them, `git add` the files, then run `GIT_EDITOR=true git rebase --continue` until the rebase is done. Do not push.".to_owned(),
                ),
            ]),
            ide_bridge: false,
            budget_usd: None,
            max_live: 4,
            queue_hold_pct: None,
            auto_park_after_mins: 45,
        }
    }
}

