pub struct AccountConfig {
    pub kind: AccountKind,
    /// github: `https://api.github.com`; gitlab: `https://gitlab.com`; linear: `https://api.linear.app`; bitbucket: `https://api.bitbucket.org/2.0`; required for jira/redmine/gitea.
    #[serde(default)]
    pub base_url: Option<String>,
    #[serde(default)]
    pub flavor: JiraFlavor,
    /// Default per kind: jira cloud `basic`, dc `bearer`, redmine `api_key`, github/gitlab/gitea `token`, bitbucket `basic` (account `email` + API token; `bearer` for repository/workspace access tokens), linear raw API key (`bearer` for OAuth).
    #[serde(default)]
    pub auth: Option<AuthKind>,
    #[serde(default)]
    pub email: Option<String>,
    #[serde(default)]
    pub user: Option<String>,
    /// Default github `gh-cli`, gitlab `glab-cli`.
    #[serde(default)]
    #[schemars(extend("x-kelta-secret" = true))]
    pub secret: Option<SecretRef>,
    #[serde(default)]
    pub text_format: TextFormat,
    #[serde(default)]
    pub poll_secs: Option<u32>,
    /// Browser links (GHE/GitLab); derived when absent.
    #[serde(default)]
    pub web_url: Option<String>,
    /// `plugin_tracker` / `plugin_codehost`: id of the plugin whose `[provider]` serves this account.
    #[serde(default)]
    pub plugin: Option<String>,
}

impl AccountConfig {
    /// `base_url` with per-kind defaults.
    pub fn effective_base_url(&self) -> Option<String> {
        self.base_url.clone().or_else(|| match self.kind {
            AccountKind::Github => Some("https://api.github.com".into()),
            AccountKind::Gitlab => Some("https://gitlab.com".into()),
            AccountKind::Linear => Some("https://api.linear.app".into()),
            AccountKind::Bitbucket => Some("https://api.bitbucket.org/2.0".into()),
            _ => None,
        })
    }

    /// `secret` with per-kind defaults.
    pub fn effective_secret(&self) -> Option<SecretRef> {
        self.secret.clone().or_else(|| match self.kind {
            AccountKind::Github => Some(SecretRef::new("gh-cli")),
            AccountKind::Gitlab => Some(SecretRef::new("glab-cli")),
            _ => None,
        })
    }
}

