/// A start option: one value is a checkbox, several a single choice. The picked values go
/// to the Claude prompt's `{options}`, else after it, in the declared order.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct StartOption {
    pub label: String,
    /// e.g. `["--auto"]`, or `["--mode=quick", "--mode=skip"]`.
    pub values: Vec<String>,
}

/// SETTINGS §2 defaults.
pub fn default_session_templates() -> Vec<SessionTemplate> {
    let t = |id: &str, label: &str, layout: TemplateNode| SessionTemplate {
        id: id.to_owned(),
        label: label.to_owned(),
        layout,
        enabled: true,
        options: Vec::new(),
    };
    vec![
        t(
            "claude+editor",
            "Claude + editor",
            TemplateNode::Split {
                split: SplitDir::Row,
                ratios: vec![0.5, 0.5],
                children: vec![TemplateNode::session("claude"), TemplateNode::session("editor")],
            },
        ),
        t(
            "review",
            "Review",
            TemplateNode::Split {
                split: SplitDir::Row,
                ratios: vec![0.5, 0.5],
                children: vec![
                    TemplateNode::Session {
                        session: s("claude"),
                        name: None,
                        profile: Some(s("review")),
                        command: None,
                    },
                    TemplateNode::Split {
                        split: SplitDir::Column,
                        ratios: vec![0.75, 0.25],
                        children: vec![
                            TemplateNode::session("editor"),
                            TemplateNode::Session {
                                session: s("shell"),
                                name: None,
                                profile: None,
                                command: Some(s("git diff --stat origin/{base}...HEAD")),
                            },
                        ],
                    },
                ],
            },
        ),
        t("claude", "Claude", TemplateNode::session("claude")),
        t("editor", "Editor", TemplateNode::session("editor")),
        t("shell", "Shell", TemplateNode::session("shell")),
    ]
}

