/// How the tracker marks a ticket blocked.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum BlockedMarker {
    /// The status name reads blocked, on hold, waiting or impediment.
    Status,
    /// The Jira flag (Impediment).
    Flag,
    /// A Linear blocked-by relation to an open issue.
    Relation,
    /// This label (case-insensitive).
    Label(String),
}

impl BlockedMarker {
    /// Flag on Jira, relation on Linear, status elsewhere.
    pub fn default_for(kind: TrackerKind) -> Self {
        match kind {
            TrackerKind::Jira => Self::Flag,
            TrackerKind::Linear => Self::Relation,
            _ => Self::Status,
        }
    }

    /// Whether `t` carries this marker; flag and relation are the provider's `Ticket.blocked`.
    pub fn on(&self, t: &Ticket) -> bool {
        match self {
            Self::Status => is_blocked_status(&t.status.name),
            Self::Flag | Self::Relation => t.blocked,
            Self::Label(l) => t.labels.iter().any(|x| x.eq_ignore_ascii_case(l)),
        }
    }

    /// Kelta can set and clear it on `kind`: statuses by transition, the rest by `Tracker::set_blocked`.
    pub fn writable(&self, kind: TrackerKind) -> bool {
        match self {
            Self::Status => true,
            Self::Flag => kind == TrackerKind::Jira,
            Self::Relation => false,
            Self::Label(_) => matches!(
                kind,
                TrackerKind::Jira
                    | TrackerKind::GithubIssues
                    | TrackerKind::GitlabIssues
                    | TrackerKind::GiteaIssues
            ),
        }
    }
}

impl Source {
    /// The binding a project sees: the tracker with this project's routes as `repo_rules`.
    pub fn binding_for(&self, project: &ProjectId) -> TrackerBinding {
        let rules = self.routes.iter().filter(|r| &r.project == project);
        TrackerBinding {
            repo_rules: rules
                .map(|r| RepoRule { r#match: r.r#match.clone(), repo: r.repo.clone() })
                .collect(),
            ..self.tracker.clone()
        }
    }
}

/// Same account and same set of views, each with its account resolved (what `tickets_key` hashes).
fn same_views(a: &TrackerBinding, b: &TrackerBinding) -> bool {
    let views = |t: &TrackerBinding| -> Vec<(AccountId, TrackerView)> {
        t.views.iter().map(|v| (v.account.clone().unwrap_or_else(|| t.account.clone()), v.clone())).collect()
    };
    let (x, y) = (views(a), views(b));
    a.account == b.account && x.len() == y.len() && x.iter().all(|v| y.contains(v))
}

fn same_board(a: &TrackerBinding, b: &TrackerBinding) -> bool {
    same_views(a, b) && a.columns == b.columns && a.status_map == b.status_map
}

/// Lowercase `[a-z0-9-]*`: runs of anything else become one `-`, none at either end (empty when
/// nothing is left; callers pick their own fallback).
pub fn slug(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars().flat_map(char::to_lowercase) {
        if c.is_ascii_alphanumeric() {
            out.push(c);
        } else if !out.ends_with('-') {
            out.push('-');
        }
    }
    out.trim_matches('-').to_owned()
}

/// `existing` plus the projects' deprecated `[project.tracker]` blocks (the migration and the read
/// path): a board equal to a source's (account, views, columns, status_map) joins it, the
/// project and its `repo_rules` as routes; another becomes a new source, labelled after its only
/// view or its account, plus ` · <project name>` when another source has the same views but
/// other columns or status_map. Ids are the label's slug, made unique with `-2`, `-3`, ….
/// An account-less block takes `source_account`; one without any account is skipped.
pub fn sources_from_trackers(existing: &[Source], projects: &[ProjectConfig]) -> Vec<Source> {
    let mut out = existing.to_vec();
    for p in projects {
        let Some(t) = &p.tracker else { continue };
        let Some(account) = t.source_account() else { continue };
        let tracker = TrackerBinding { account, repo_rules: Vec::new(), ..t.clone() };
        let i = match out.iter().position(|s| same_board(&s.tracker, &tracker)) {
            Some(i) => i,
            None => {
                out.push(Source { tracker, ..Source::default() });
                out.len() - 1
            }
        };
        let s = &mut out[i];
        if !s.projects.contains(&p.id) {
            s.projects.push(p.id.clone());
        }
        for r in &t.repo_rules {
            let route = SourceRoute {
                r#match: r.r#match.clone(),
                project: p.id.clone(),
                repo: r.repo.clone(),
                ..SourceRoute::default()
            };
            if !s.routes.contains(&route) {
                s.routes.push(route);
            }
        }
    }
    for i in existing.len()..out.len() {
        let t = &out[i].tracker;
        let mut label = match t.views.as_slice() {
            [v] if !v.label.is_empty() => v.label.clone(),
            [v] if !v.id.is_empty() => v.id.clone(),
            _ => t.account.to_string(),
        };
        if out.iter().enumerate().any(|(j, s)| j != i && same_views(&s.tracker, t)) {
            let first = projects.iter().find(|p| out[i].projects.first() == Some(&p.id));
            let name = first.map(|p| if p.name.is_empty() { p.id.to_string() } else { p.name.clone() });
            label = format!("{label} · {}", name.unwrap_or_default());
        }
        let base = Some(slug(&label)).filter(|s| !s.is_empty()).unwrap_or_else(|| "source".into());
        let (mut id, mut n) = (base.clone(), 2);
        while out.iter().any(|s| s.id == id) {
            id = format!("{base}-{n}");
            n += 1;
        }
        out[i].id = id;
        out[i].label = label;
    }
    out
}

/// A project or status colour: `theme:<slot>` or a hex.
const COLOR_PATTERN: &str =
    r"^(#[0-9a-fA-F]{6}|#[0-9a-fA-F]{3}|theme:(bright-)?(red|green|yellow|blue|magenta|cyan))$";

/// `[project]` table.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct ProjectConfig {
    /// Must equal the file stem.
    pub id: ProjectId,
    pub name: String,
    /// `theme:<slot>` follows the active theme's ANSI colour (`red`..`cyan`, `bright-red`..`bright-cyan`);
    /// a `#rrggbb` hex stays as typed (`#rgb` reads as `#rrggbb`).
    #[schemars(regex(pattern = COLOR_PATTERN))]
    pub color: Option<String>,
    /// 1-2 chars or sprite icon name.
    pub icon: Option<String>,
    pub default_template: Option<String>,
    pub repos: Vec<RepoConfig>,
    /// Deprecated: boards live in the global `[[sources]]`. Still read for one release, and moved
    /// there at startup (SETTINGS §3).
    #[schemars(extend("deprecated" = true))]
    pub tracker: Option<TrackerBinding>,
}

/// Whole `projects/<id>.toml`: the `[project]` table plus project-scoped overrides of global keys.
